using System;using System.IO;using System.Xml;using System.Xml.Serialization;using System.Collections.Generic;
public class Offline70ItemMetadataDocumentFG {public int Format=1;public string PvfSha256;public List<Offline70EconomyItemDefinition> Items=new List<Offline70EconomyItemDefinition>();}
class Offline70ItemMetadataFG {
 internal static void Register(string path){if(new FileInfo(path).Length>8388608)throw new InvalidDataException("Item metadata size");Offline70ItemMetadataDocumentFG d;using(FileStream f=File.OpenRead(path))using(XmlTextReader r=new XmlTextReader(f)){r.ProhibitDtd=true;r.XmlResolver=null;d=(Offline70ItemMetadataDocumentFG)new XmlSerializer(typeof(Offline70ItemMetadataDocumentFG)).Deserialize(r);}if(d.Format!=1||d.PvfSha256!=Offline70QuestCatalogFG.CurrentPvf||d.Items==null||d.Items.Count>10000)throw new InvalidDataException("Item metadata profile");HashSet<uint> seen=new HashSet<uint>();foreach(Offline70EconomyItemDefinition item in d.Items){if(!seen.Add(item.ItemId))throw new InvalidDataException("Duplicate item metadata");bool exists=true;try{Offline70Economy.Definition(item.ItemId);}catch(InvalidDataException){exists=false;}if(!exists)Offline70Economy.RegisterMetadata(item);}}
}
